insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('IE', 'default', 'Ireland reference chart of accounts', '{}'::jsonb, true, 'companies', array['IE-CA-SMALL-BS', 'IE-CA-SMALL-IS']::text[], null, 'There is no legal chart of accounts in Ireland. Companies Act 2014, s. 282 requires a company to keep adequate accounting records and prescribes none; s. 291(1) and (3) require the entity financial statements to comprise a balance sheet and a profit and loss account that comply, for a company in the small companies regime (s. 280A), with Schedule 3A, and otherwise with Schedule 3; s. 291(2) requires them to give a true and fair view, and applicable accounting standards — FRS 102, and FRS 105 for a micro company under Schedule 3B — govern recognition and measurement. This chart is original: it follows the four-digit convention Irish practice shares with British practice, and every block of codes maps onto one item of Balance Sheet Format 1 or of Profit and Loss Account Format 1 of Schedule 3A, so that the statements of this pack read straight off the chart.', 'ca-2014')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

