values
  ('IE-CA-SMALL-BS', 'IE', 'default', 'Balance sheet — Companies Act 2014, Schedule 3A, Format 1 (small companies regime)', 'balance_sheet', 'IE-FRS102', date '1970-01-01', null, 'Companies Act 2014, Schedule 3A, Part II, Section B — Balance Sheet Formats, Format 1, as inserted by the Companies (Accounting) Act 2017. Section 291(3)(a)(ii) of the Act has a company that qualifies for the small companies regime (s. 280A) comply with Schedule 3A, or with Schedule 3 if it so elects; paragraph 2(1) of Schedule 3A requires the items of the format adopted, in its order and under its headings. Every letter and numeral below is an item of Format 1 and the name is the format''s own wording.', 'ca-2014'),
  ('IE-CA-SMALL-IS', 'IE', 'default', 'Profit and loss account — Companies Act 2014, Schedule 3A, Format 1 (small companies regime)', 'income_statement', 'IE-FRS102', date '1970-01-01', null, 'Companies Act 2014, Schedule 3A, Part II, Section B — Profit and Loss Account Formats, Format 1, which classifies expenses by function. Items 1 to 16 are the format''s own numbering.', 'ca-2014')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

