  ('IE-CA-SMALL-BS', 'NET', null, 'Net assets (liabilities)', '{}'::jsonb, 680, 1, true, array['E']::text[], array['F', 'G']::text[], null, 'Not an item of Format 1, which goes from item G to the capital and reserves of item H. It is the figure items A to G produce, printed so that a reader can see it agree with item H. It agrees only once the year is closed: until close_fiscal_year() carries the result onto item H.VI, net assets exceed capital and reserves by exactly the profit of the profit and loss account.', null),
