  ('IE-CA-SMALL-BS', 'H.IV.3', 'H.IV', 'Reserves provided for by the constitution', '{}'::jsonb, 760, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('IE-CA-SMALL-BS', 'H.IV.4', 'H.IV', 'Other reserves including the fair value reserve', '{}'::jsonb, 770, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('IE-CA-SMALL-BS', 'H.V', 'H', 'Profit or loss brought forward', '{}'::jsonb, 780, -1, false, '{}'::text[], '{}'::text[], null, 'Note (8) on the balance sheet formats allows items H.V and H.VI to be combined where the appropriation of profit is given at the foot of the profit and loss account or in a note. This pack keeps them apart, and a dividend, which is not part of a close, is booked here by hand.', null),
