update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'European Communities (Late Payment in Commercial Transactions) Regulations 2012, reg. 5(1) — statutory late payment interest at the European Central Bank''s main refinancing rate before 1 January or 1 July plus 8 percentage points; reg. 9 and the Schedule — compensation of €40 up to €1,000, €70 up to €10,000 and €100 above, with reasonable recovery costs beyond it',
  numbering_legal_reference     = 'Value-Added Tax Regulations 2010, reg. 20(2)(b) — every invoice carries “a sequential number, based on one or more series, which uniquely identifies the invoice”. The text requires a sequence, series and uniqueness and prescribes no shape and no rule against a hole, which is why `numbering` is `sequential` and not gapless, and the pattern declared in number_format is one series the regulation allows rather than a form it prescribes. Reg. 20(5)(b) asks of a credit note only a number that uniquely identifies it.',
  numbering_source_key          = 'vat-regs-2010',
  payment_terms_legal_reference = 'European Communities (Late Payment in Commercial Transactions) Regulations 2012, reg. 2(1), definition of “relevant payment date” — where the contract specifies no date or period for payment, the date falling 30 calendar days after the purchaser receives the invoice, or after delivery where the date of receipt is uncertain or the invoice came first; where the contract specifies a date more than 60 calendar days after delivery, it has to be expressly agreed and not grossly unfair to the supplier. Thirty days is therefore the term the law sets in the absence of an agreement.',
  payment_terms_source_key      = 'late-payment-regs-2012',
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Value-Added Tax Consolidation Act 2010, s. 74(1) — tax on a supply is due, where an invoice is required under Chapter 2 of Part 9 (a supply to another accountable person, a public body, a person carrying on an exempted activity or a person in another Member State, s. 66(1)), at the time the invoice is issued or, if it is not issued in due time, when the period for issuing it expires (paragraph (a)), and in any other case at the time the goods or services are supplied (paragraph (d)); s. 74(2) brings it forward to a payment received before the supply. The supply is the principle and a required invoice displaces it, which is what `invoice_if_issued` says; the prepayment rule of s. 74(2) is not carried by the word, and the moneys received basis of s. 80 is carried by the taxes that declare cash_basis.',
  tax_point_source_key          = 'vatca-2010',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = 'peppol-bis-3',
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'No Irish enactment obliges a business to issue an electronic invoice to another business today, so mandatory_from is empty. Value-Added Tax Consolidation Act 2010, s. 66(2) — an electronic invoice counts as issued only where issuer and recipient have agreed to it beforehand. The European Union (Electronic Invoicing in Public Procurement) Regulations 2019, reg. 4, oblige a contracting authority — a sub-central one from 18 April 2020 (reg. 3(6)) — to receive and process an electronic invoice that complies with EN 16931, which is an obligation of the public buyer and not of the supplier. Revenue has announced a phased mandate — VAT-registered large corporates to issue e-invoices and report domestic B2B transactions from November 2028, businesses trading cross-border in the Union from November 2029, the ViDA requirements from July 2030, and every business able to receive structured e-invoices from the first phase — but none of it is enacted yet, so no date is written here. The profile declared is what Irish Peppol participants exchange and is not a legal requirement. The two identifiers are ISO 6523 codes of the Peppol electronic address scheme list: 0088 is the Global Location Number, because that list carries no code for a CRO company number; 9935 is the Ireland VAT number.',
  einvoice_source_key           = 'revenue-vat-modernisation',
  party_scheme                  = '0088',
  vat_scheme                    = '9935',
  bank_statement_formats        = array['camt.053']::text[],
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'IE';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('IE', 'reverse_charge', 'reverse_charge', 'VAT on this supply to be accounted for by the principal contractor.', '{}'::jsonb, 10, date '1970-01-01', null, 'Value-Added Tax Consolidation Act 2010, s. 66(4)(a) — a subcontractor supplying a service to which s. 16(3) applies issues a document indicating that the principal is liable to account for the tax chargeable on the supply. The sentence is the one Revenue''s manual on construction services asks the invoice to carry. The only sale-side reverse charge this pack carries is that one, so the sentence names the principal contractor; the other domestic reverse charges of s. 16 — emission allowances, scrap metal, construction work between connected persons, gas and electricity to a dealer — would each want the recipient named instead, and are recorded as out of scope in the README.'),
  ('IE', 'intracom_goods', 'intra_eu_goods', 'Intra-Community supply of goods — zero-rated under Schedule 2, paragraph 1(1) of the Value-Added Tax Consolidation Act 2010 (Article 138 of Directive 2006/112/EC).', '{}'::jsonb, 20, date '1970-01-01', null, 'Value-Added Tax Regulations 2010, reg. 20(2)(f) — on a supply of goods to a person registered for VAT in another Member State, the invoice carries that person''s VAT number and an indication that it relates to an intra-Community supply of goods.'),
  ('IE', 'intracom_services', 'intra_eu_services', 'Reverse charge — the customer is liable to account for the VAT (Articles 44 and 196 of Directive 2006/112/EC).', '{}'::jsonb, 30, date '1970-01-01', null, 'Value-Added Tax Regulations 2010, reg. 20(1) and 20(2)(e) — on a supply to a person in another Member State who is liable to pay the VAT on it, the invoice carries that person''s VAT number and an indication that a reverse charge applies.'),
  ('IE', 'export', 'export', 'Export of goods outside the European Union — zero-rated under Schedule 2, paragraph 3 of the Value-Added Tax Consolidation Act 2010.', '{}'::jsonb, 40, date '1970-01-01', null, 'Value-Added Tax Regulations 2010, reg. 20(2)(j) — the invoice states the consideration per rate of tax and the rate chargeable, which on an export is the zero rate of Schedule 2, paragraph 3.'),
  ('IE', 'exempt', 'exempt', 'Exempt from VAT under Schedule 1 of the Value-Added Tax Consolidation Act 2010.', '{}'::jsonb, 50, date '1970-01-01', null, 'Value-Added Tax Regulations 2010, reg. 20(2)(j) — an invoice states the consideration per rate of tax and the rate chargeable; an exempted activity is charged at none, and the sentence says under which Schedule of the Act it is exempt.'),
  ('IE', 'late_payment', 'late_payment', 'If this invoice is not paid by the relevant payment date, the supplier is entitled to statutory late payment interest at the European Central Bank reference rate plus 8 percentage points and to compensation for recovery costs, under the European Communities (Late Payment in Commercial Transactions) Regulations 2012.', '{}'::jsonb, 60, date '1970-01-01', null, 'European Communities (Late Payment in Commercial Transactions) Regulations 2012, reg. 4(1) and reg. 5(1) — statutory late payment interest is an implied term of every commercial transaction, at the reference rate plus 8 percentage points; reg. 9 and the Schedule — compensation for recovery costs of €40, €70 or €100 according to the amount.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
